import fs from 'node:fs';
import path from 'node:path';
import { checkIosBundle, checkIosReleaseGraph } from './release-guard.ts';
const graph = checkIosReleaseGraph(process.cwd());
if (graph.errors.length) throw new Error(graph.errors.join('\n'));
const dir = 'apps/mobile/dist/_expo/static/js/ios';
const bundles = fs.readdirSync(dir).filter(name => name.endsWith('.hbc') || name.endsWith('.js'));
if (bundles.length !== 1) throw new Error('Expected one freshly exported iOS bundle; run mobile:bundle.');
const bundle = fs.readFileSync(path.join(dir, bundles[0]));
const errors = checkIosBundle(bundle);
if (errors.length) throw new Error(errors.join('\n'));
console.log(`iOS bundle isolation passed: real HealthLoopHealth module present; excluded native providers/fixtures absent; source/dependency graph checked (${graph.sourceCount} sources, ${graph.packageCount} manifests). This is not a signed-device or App Review result.`);
